import sys, math, itertools, random, heapq, bisect
from collections import Counter, deque, defaultdict
from functools import lru_cache

def room_assignment(text):
    v = list(map(int, text.split()))
    (n, k) = v[:2]
    caps = v[2:2 + n]
    needs = v[2 + n:]

    @lru_cache(None)
    def feasible(capacities, students):
        if not students:
            return True
        if sum(capacities) < sum(students) or not capacities or max(capacities) < max(students):
            return False
        capacities = tuple(sorted(capacities, reverse=True))
        students = tuple(students)
        r = len(students)
        total = (1 << r) - 1
        sums = [0] * (total + 1)
        for mask in range(1, total + 1):
            bit = mask & -mask
            sums[mask] = sums[mask ^ bit] + students[bit.bit_length() - 1]

        @lru_cache(None)
        def assign(i, mask):
            if not mask:
                return True
            if i == len(capacities):
                return False
            if sums[mask] <= capacities[i]:
                return True
            sub = mask
            while sub:
                if sums[sub] <= capacities[i] and assign(i + 1, mask ^ sub):
                    return True
                sub = sub - 1 & mask
            return assign(i + 1, mask)
        return assign(0, total)
    if not feasible(tuple(sorted(caps)), tuple(needs)):
        return '-1'
    answer = []
    for (i, need) in enumerate(needs):
        for j in range(n):
            if caps[j] < need:
                continue
            caps[j] -= need
            if feasible(tuple(sorted(caps)), tuple(needs[i + 1:])):
                answer.append(j + 1)
                break
            caps[j] += need
        else:
            raise AssertionError('可行性与字典序选择不一致')
    return ' '.join(map(str, answer))
import sys
sys.stdout.write(room_assignment(sys.stdin.read()) + '\n')

import sys, math, itertools, random, heapq, bisect
