def make_increasing(text):
    rows = text.splitlines()
    a = list(map(int, rows[0].split()))
    b = sorted(set(map(int, rows[1].split())))
    states = {-1: 0}
    for value in a:
        nxt = {}
        for (last, used) in states.items():
            if value > last:
                nxt[value] = min(nxt.get(value, 10 ** 9), used)
            at = bisect.bisect_right(b, last)
            if at < len(b):
                nxt[b[at]] = min(nxt.get(b[at], 10 ** 9), used + 1)
        states = {}
        best = 10 ** 9
        for last in sorted(nxt):
            if nxt[last] < best:
                states[last] = nxt[last]
                best = nxt[last]
        if not states:
            return '-1'
    return str(min(states.values()))
import sys
sys.stdout.write(make_increasing(sys.stdin.read()) + '\n')

import sys, math, itertools, random, heapq, bisect
from collections import Counter, deque, defaultdict
from functools import lru_cache

def time_machine(text):
    v = list(map(int, text.split()))
    out = []
    for (s, t) in zip(v[1::2], v[2::2]):
        if s == t:
            out.append('0')
            continue
        limit = 2 * max(s, t) + 2
        front = {s}
        back = {t}
        d1 = {s: 0}
        d2 = {t: 0}
        distance = None
        while front and back:
            if len(front) > len(back):
                (front, back) = (back, front)
                (d1, d2) = (d2, d1)
            nxt = set()
            best = 10 ** 9
            for u in front:
                for x in (u - 1, u + 1, 2 * u, u // 2 if u % 2 == 0 else -1):
                    if not 0 < x <= limit or x in d1:
                        continue
                    if x in d2:
                        best = min(best, d1[u] + 1 + d2[x])
                    d1[x] = d1[u] + 1
                    nxt.add(x)
            if best < 10 ** 9:
                distance = best
                break
            front = nxt
        assert distance is not None
        out.append(str(2 * distance))
    return '\n'.join(out)
import sys
sys.stdout.write(time_machine(sys.stdin.read()) + '\n')

import sys, math, itertools, random, heapq, bisect
