def magic_square(text):
    v = list(map(int, text.split()))
    (m, n) = v[:2]
    a = [v[2 + i * n:2 + (i + 1) * n] for i in range(m)]
    row = [[0] * (n + 1) for i in range(m)]
    col = [[0] * n for i in range(m + 1)]
    d1 = [[0] * (n + 1) for i in range(m + 1)]
    d2 = [[0] * (n + 1) for i in range(m + 1)]
    for i in range(m):
        for j in range(n):
            row[i][j + 1] = row[i][j] + a[i][j]
            col[i + 1][j] = col[i][j] + a[i][j]
            d1[i + 1][j + 1] = d1[i][j] + a[i][j]
        for j in range(n - 1, -1, -1):
            d2[i + 1][j] = d2[i][j + 1] + a[i][j]
    for k in range(min(m, n), 1, -1):
        r = [[row[i][j + k] - row[i][j] for j in range(n - k + 1)] for i in range(m)]
        c = [[col[i + k][j] - col[i][j] for j in range(n)] for i in range(m - k + 1)]
        rr = [[1] * (n - k + 1) for i in range(m)]
        cc = [[1] * n for i in range(m - k + 1)]
        for i in range(m - 2, -1, -1):
            for j in range(n - k + 1):
                if r[i][j] == r[i + 1][j]:
                    rr[i][j] = rr[i + 1][j] + 1
        for i in range(m - k + 1):
            for j in range(n - 2, -1, -1):
                if c[i][j] == c[i][j + 1]:
                    cc[i][j] = cc[i][j + 1] + 1
        for i in range(m - k + 1):
            for j in range(n - k + 1):
                if rr[i][j] >= k and cc[i][j] >= k and (r[i][j] == c[i][j] == d1[i + k][j + k] - d1[i][j] == d2[i + k][j] - d2[i][j + k]):
                    return str(k)
    return '1'
import sys
sys.stdout.write(magic_square(sys.stdin.read()) + '\n')

