def posters(text):
    v = list(map(int, text.split()))
    stack = []
    answer = 0
    for h in v[2::2]:
        while stack and stack[-1] > h:
            stack.pop()
        if not stack or stack[-1] < h:
            stack.append(h)
            answer += 1
    return str(answer)
import sys
