def brackets(text):
    lines = text.splitlines()
    out = []
    pairs = dict(zip('}]>)', '{[<('))
    rank = {'{': 0, '[': 1, '(': 2, '<': 3}
    for expression in lines[1:]:
        stack = []
        good = True
        for c in expression:
            if c in rank:
                if stack and rank[c] < rank[stack[-1]]:
                    good = False
                    break
                stack.append(c)
            elif c in pairs and stack and (pairs[c] == stack[-1]):
                stack.pop()
            else:
                good = False
                break
        out.append('YES' if good and (not stack) else 'NO')
    return '\n'.join(out)
import sys
sys.stdout.write(brackets(sys.stdin.read()) + '\n')

import sys, math, itertools, random, heapq, bisect
from collections import Counter, deque, defaultdict
from functools import lru_cache

def simplify_path(text):
    parts = []
    for part in text.rstrip('\r\n').split('/'):
        if part in ('', '.'):
            continue
        if part == '..':
            if parts:
                parts.pop()
        else:
            parts.append(part)
    return '/' + '/'.join(parts)
import sys
sys.stdout.write(simplify_path(sys.stdin.read()) + '\n')

